import{_ as o,o as d,c as t,a2 as i}from"./chunks/framework.D0_YsCyK.js";const p=JSON.parse('{"title":"审查域 A 报告：订阅全链路","description":"","frontmatter":{},"headers":[],"relativePath":"audit/A-subscription.md","filePath":"audit/A-subscription.md","lastUpdated":1792447441000}'),c={name:"audit/A-subscription.md"};function a(r,e,l,n,s,u){return d(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="审查域-a-报告-订阅全链路" tabindex="-1">审查域 A 报告：订阅全链路 <a class="header-anchor" href="#审查域-a-报告-订阅全链路" aria-label="Permalink to &quot;审查域 A 报告：订阅全链路&quot;">​</a></h1><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><ul><li>审查范围：订阅配置读写闭环、渲染正确性、脚本安全性、流量配额、订阅分配、对外端点</li><li>发现问题数：<strong>P0 1 个</strong> / P1 0 个 / P2 2 个 / P3 1 个</li><li>实际执行的测试： <ul><li>Go 单元测试：<code>TestScriptTimeoutActual</code>（死循环脚本 1.004s 超时）、<code>TestScriptFieldEscape</code>（字段无逃逸）、<code>TestScriptInvalidIDSkipped</code>（非法 ID 跳过）——全部通过</li><li>内核测试套件：<code>go test ./internal/kernel/</code> 通过</li><li>代码审查：<code>subPipeline</code> vs <code>SubOptions</code> 字段逐项对照、<code>ApplySubOptions</code> 流水线顺序、<code>subURLSig</code> HMAC、<code>subOverQuota</code>/<code>lastResetAt</code> 逻辑</li></ul></li></ul><h2 id="p0-阻断" tabindex="-1">P0 阻断 <a class="header-anchor" href="#p0-阻断" aria-label="Permalink to &quot;P0 阻断&quot;">​</a></h2><h3 id="a-001-订阅规则与脚本在-http-层被完全丢弃" tabindex="-1">A-001 订阅规则与脚本在 HTTP 层被完全丢弃 <a class="header-anchor" href="#a-001-订阅规则与脚本在-http-层被完全丢弃" aria-label="Permalink to &quot;A-001 订阅规则与脚本在 HTTP 层被完全丢弃&quot;">​</a></h3><ul><li>文件：<code>go-backend/internal/http/handler/subscription.go:30-52</code></li><li>现象：前端发送的 <code>rules</code>、<code>ruleGroups</code>、<code>script</code>、<code>chainLandingNames</code>、<code>chainRelayNames</code> 五个字段，在后端被静默丢弃，订阅规则引擎和脚本功能在 Web 层完全不可用。</li><li>复现步骤： <ol><li>前端 <code>vite-frontend/src/api/index.ts:661-683</code> 的 <code>SubPipeline</code> 接口包含全部 18 个字段（含上述 5 个）。</li><li>前端 <code>vite-frontend/src/pages/subscription.tsx:76-80</code> 设置默认值并通过 <code>toPayload</code> 的 <code>...rest</code> 展开发送。</li><li>后端 <code>subscription.go:30-44</code> 的 <code>subPipeline</code> 结构体仅有 13 个字段，缺失上述 5 个。</li><li><code>encoding/json</code> 反序列化时未知字段被静默丢弃。</li><li><code>subscription.go:46-51</code> 的 <code>options()</code> 方法未映射这 5 个字段。</li><li><code>subscription.go:558-559</code> 的 <code>SaveSubscription</code> 执行 <code>json.Marshal(req.Options)</code>，数据库中永远存不下这 5 个字段。</li><li><code>subscription.go:727</code> 的预览路径同样调用 <code>req.Options.options()</code>，同样丢失。</li></ol></li><li>期望：前端配置的规则/脚本能保存到数据库并在渲染时生效。</li><li>实际：三处（保存、预览、渲染）全部丢失，只有直接调用 <code>kernel.SubOptions</code> 的单元测试能通过。</li><li>影响范围：订阅规则引擎（10 个规则组）、订阅 JS 脚本、链式代理多选（<code>ChainLandingNames</code>/<code>ChainRelayNames</code>）三个移植功能在生产环境完全不可用。</li><li>修复方向：在 <code>subPipeline</code> 补 5 个字段（带正确的 <code>json</code> tag）、在 <code>options()</code> 补映射、在 <code>normalize()</code> 补长度校验（<code>Script</code> 20000 字符、<code>RuleGroups</code> 数量上限）。</li></ul><h3 id="字段对照表-a1" tabindex="-1">字段对照表（A1） <a class="header-anchor" href="#字段对照表-a1" aria-label="Permalink to &quot;字段对照表（A1）&quot;">​</a></h3><table tabindex="0"><thead><tr><th><code>kernel.SubOptions</code> 字段</th><th><code>subPipeline</code> 有无</th><th><code>options()</code> 映射</th><th>状态</th></tr></thead><tbody><tr><td>Lines</td><td>✅</td><td>✅</td><td>正常</td></tr><tr><td>Regions</td><td>✅</td><td>✅</td><td>正常</td></tr><tr><td>Protocols</td><td>✅</td><td>✅</td><td>正常</td></tr><tr><td>Include</td><td>✅</td><td>✅</td><td>正常</td></tr><tr><td>Exclude</td><td>✅</td><td>✅</td><td>正常</td></tr><tr><td>Rename</td><td>✅</td><td>✅</td><td>正常</td></tr><tr><td>AddFlag</td><td>✅</td><td>✅</td><td>正常</td></tr><tr><td>Prefix</td><td>✅</td><td>✅</td><td>正常</td></tr><tr><td>Dedupe</td><td>✅</td><td>✅</td><td>正常</td></tr><tr><td>Sort</td><td>✅</td><td>✅</td><td>正常</td></tr><tr><td>RegionGroups</td><td>✅</td><td>✅</td><td>正常</td></tr><tr><td>ChainLandingNames</td><td>❌</td><td>❌</td><td><strong>P0-1 断点</strong></td></tr><tr><td>ChainRelayNames</td><td>❌</td><td>❌</td><td><strong>P0-1 断点</strong></td></tr><tr><td>ChainLanding</td><td>✅</td><td>✅</td><td>正常（旧字段兼容）</td></tr><tr><td>ChainRelay</td><td>✅</td><td>✅</td><td>正常（旧字段兼容）</td></tr><tr><td>Script</td><td>❌</td><td>❌</td><td><strong>P0-1 断点</strong></td></tr><tr><td>Rules</td><td>❌</td><td>❌</td><td><strong>P0-1 断点</strong></td></tr><tr><td>RuleGroups</td><td>❌</td><td>❌</td><td><strong>P0-1 断点</strong></td></tr></tbody></table><h2 id="p1-严重" tabindex="-1">P1 严重 <a class="header-anchor" href="#p1-严重" aria-label="Permalink to &quot;P1 严重&quot;">​</a></h2><p>（无）</p><h2 id="p2-一般" tabindex="-1">P2 一般 <a class="header-anchor" href="#p2-一般" aria-label="Permalink to &quot;P2 一般&quot;">​</a></h2><h3 id="a-002-applysuboptions-中脚本错误被静默吞掉-调用方无法区分-无脚本-和-脚本失败" tabindex="-1">A-002 <code>ApplySubOptions</code> 中脚本错误被静默吞掉，调用方无法区分&quot;无脚本&quot;和&quot;脚本失败&quot; <a class="header-anchor" href="#a-002-applysuboptions-中脚本错误被静默吞掉-调用方无法区分-无脚本-和-脚本失败" aria-label="Permalink to &quot;A-002 `ApplySubOptions` 中脚本错误被静默吞掉，调用方无法区分&quot;无脚本&quot;和&quot;脚本失败&quot;&quot;">​</a></h3><ul><li>文件：<code>go-backend/internal/kernel/sub_options.go:258-260</code></li><li>现象：<code>if scripted, err := ApplySubScript(out, opts.Script); err == nil { out = scripted }</code> —— 脚本执行失败时 <code>err</code> 被丢弃，直接使用脚本执行前的 <code>out</code>。虽然注释说明&quot;编辑器会显示错误（SubScriptError）&quot;，但 <code>SubScriptError</code> 需要重新执行一次脚本（<code>sub_options.go:273</code>），存在重复执行开销，且正常渲染路径无法感知脚本失败。</li><li>影响：用户看到的订阅是&quot;脚本失败前的结果&quot;，而编辑器显示脚本有错，两处状态不一致时难以排查。</li><li>修复方向：在 <code>SubOptions</code> 或返回值中携带脚本错误，或在日志中记录。</li></ul><h3 id="a-003-normalize-未校验新增字段的长度-合法性" tabindex="-1">A-003 <code>normalize()</code> 未校验新增字段的长度/合法性 <a class="header-anchor" href="#a-003-normalize-未校验新增字段的长度-合法性" aria-label="Permalink to &quot;A-003 `normalize()` 未校验新增字段的长度/合法性&quot;">​</a></h3><ul><li>文件：<code>go-backend/internal/http/handler/subscription.go:54-80</code></li><li>现象：<code>normalize()</code> 校验了 <code>Rename</code>、<code>Include</code>、<code>Exclude</code>、<code>ChainLanding</code>、<code>ChainRelay</code>、<code>Prefix</code>、<code>Sort</code>、<code>Lines</code>，但未校验 <code>Script</code>（应 ≤20000 字符，与 <code>ValidateSubScript</code> 一致）、<code>RuleGroups</code>（应为已知规则组白名单）、<code>ChainLandingNames</code>/<code>ChainRelayNames</code>（数量上限）。</li><li>影响：恶意或误操作的超长脚本可存入数据库（<code>ValidateSubScript</code> 仅在 <code>ApplySubScript</code> 时检查，保存时不检查）。</li><li>修复方向：在 <code>normalize()</code> 中补 <code>len(p.Script) &gt; kernel.MaxScriptLength</code> 检查和规则组白名单校验。</li></ul><h2 id="p3-体验" tabindex="-1">P3 体验 <a class="header-anchor" href="#p3-体验" aria-label="Permalink to &quot;P3 体验&quot;">​</a></h2><h3 id="a-004-订阅脚本错误信息未包含行号" tabindex="-1">A-004 订阅脚本错误信息未包含行号 <a class="header-anchor" href="#a-004-订阅脚本错误信息未包含行号" aria-label="Permalink to &quot;A-004 订阅脚本错误信息未包含行号&quot;">​</a></h3><ul><li>文件：<code>go-backend/internal/kernel/sub_script.go:136-144</code></li><li>现象：<code>scriptError</code> 将 goja 的异常转为 <code>fmt.Errorf(&quot;脚本出错：%s&quot;, ...)</code>，但未提取 JS 堆栈中的行号。用户写错脚本时难以定位。</li><li>修复方向：从 <code>*goja.Exception</code> 的 <code>Stack()</code> 中解析行号并包含在错误信息中。</li></ul><h2 id="已验证通过的项" tabindex="-1">已验证通过的项 <a class="header-anchor" href="#已验证通过的项" aria-label="Permalink to &quot;已验证通过的项&quot;">​</a></h2><h3 id="a2-订阅渲染正确性" tabindex="-1">A2 订阅渲染正确性 <a class="header-anchor" href="#a2-订阅渲染正确性" aria-label="Permalink to &quot;A2 订阅渲染正确性&quot;">​</a></h3><ul><li><code>clashProfile(endpoints, groups, opts)</code> 三参数调用点（<code>share.go:548</code>）正确。</li><li><code>singboxProfile(endpoints, groups, opts)</code> 调用点（<code>share.go:565</code>）正确。</li><li>P2 回归测试（<code>share_rules_regression_test.go</code>）在移植时已验证 <code>Rules=false</code> 四格式逐字节一致。</li></ul><h3 id="a3-订阅脚本安全性-实测通过" tabindex="-1">A3 订阅脚本安全性（实测通过） <a class="header-anchor" href="#a3-订阅脚本安全性-实测通过" aria-label="Permalink to &quot;A3 订阅脚本安全性（实测通过）&quot;">​</a></h3><ul><li><strong>超时</strong>：死循环脚本在 1.004s 被中断（<code>scriptTimeout = time.Second</code>），误差在预期内。</li><li><strong>字段隔离</strong>：脚本仅能看到 <code>id/name/original/server/port/protocol/region/line</code> 8 个字段；实测修改 <code>server</code> 被忽略，仅 <code>name</code> 变更被采纳。</li><li><strong>ID 映射</strong>：返回数组中 <code>id</code> 越界（如 99）时被 <code>continue</code> 跳过，不会 panic。</li><li><strong>沙箱</strong>：<code>goja.New()</code> 裸虚拟机，无网络/文件/定时器；<code>console.log</code> 被无害化。</li></ul><h3 id="a4-订阅流量与配额" tabindex="-1">A4 订阅流量与配额 <a class="header-anchor" href="#a4-订阅流量与配额" aria-label="Permalink to &quot;A4 订阅流量与配额&quot;">​</a></h3><ul><li><code>subOverQuota</code>：<code>TrafficLimit &gt; 0 &amp;&amp; used &gt;= limit</code>，逻辑正确。</li><li><code>lastResetAt</code>：跨月天数钳制（<code>day &gt; last → day = last</code>），<code>ResetDay=29/30/31</code> 在 2 月份会钳制到 28/29，行为合理。</li><li><code>subDueReset</code>：仅对分享订阅生效，非分享订阅永不重置，符合设计。</li><li>时区：使用服务器本地时区（<code>now.Location()</code>），与 <code>syncSubscriptions</code> 的调度时区一致。</li></ul><h3 id="a5-订阅分配" tabindex="-1">A5 订阅分配 <a class="header-anchor" href="#a5-订阅分配" aria-label="Permalink to &quot;A5 订阅分配&quot;">​</a></h3><ul><li><code>subURLSig</code> 使用 <code>HMAC-SHA256(jwtSecret, &quot;flvx-subsig-v1:{userID}&quot;)</code>，<code>verifySubURLSig</code> 使用 <code>subtle.ConstantTimeCompare</code>，防时序攻击。</li><li>签名仅绑定 <code>userID</code>，<code>relay</code>/<code>inbound</code>/<code>format</code> 等参数不签名——这是正确的，因为后端在验证签名后会重新查询该用户的 <code>user_inbound</code> 分配并过滤，参数篡改无法越权（无分配则返回空）。</li><li><code>user_inbound</code> 唯一索引 <code>(user_id, inbound_id, relay_id)</code> 已在 R5 迁移中处理。</li></ul><h3 id="a6-流水线顺序" tabindex="-1">A6 流水线顺序 <a class="header-anchor" href="#a6-流水线顺序" aria-label="Permalink to &quot;A6 流水线顺序&quot;">​</a></h3><ul><li><code>ApplySubOptions</code> 顺序：过滤 → 改名 → 去重 → 排序 → <strong>脚本</strong> → <code>markChain</code>。</li><li>脚本在 <code>markChain</code> 之前执行是正确的：脚本仅被允许修改 <code>name</code>，<code>markChain</code> 按 <code>Original</code>（脚本执行前已固化）匹配 <code>ChainLandingNames</code>/<code>ChainRelayNames</code>，不受脚本改名影响。</li></ul><h2 id="未能验证的项" tabindex="-1">未能验证的项 <a class="header-anchor" href="#未能验证的项" aria-label="Permalink to &quot;未能验证的项&quot;">​</a></h2><ul><li><strong>A2 大订阅性能</strong>：1000+ 节点时 <code>clashProfile</code> 的 YAML 生成耗时，未实测（需构造大批量数据）。</li><li><strong>A4 并发配额</strong>：<code>ApplySubscriptionCounterSamples</code> 的并发写入死锁风险，未实测（需并发压测环境）。</li><li><strong>A5 端到端 IDOR</strong>：未实际启动服务测试 <code>?user=</code> 篡改，结论基于代码审查（HMAC 恒定时间比较 + 后端二次鉴权，逻辑上无漏洞）。</li><li><strong>PostgreSQL 迁移</strong>：<code>subPipeline</code> 的 JSON 字段在 PG 下的读写，未实测（沙箱无 PG）。</li></ul>',31)])])}const b=o(c,[["render",a]]);export{p as __pageData,b as default};
